import os,re
def imps(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
seen,stack=set(),['AlgebraicJacobian']
# root file is AlgebraicJacobian.lean
while stack:
    m=stack.pop()
    if m not in seen: seen.add(m); stack+=imps(m)
all_m=set()
for d,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): all_m.add(os.path.join(d,f)[:-5].replace('/','.'))
print("on disk:",len(all_m),"reachable:",len(seen&all_m))
for m in sorted(all_m-seen): print("  UNROOTED",m)
PY

